/* @autogenerated */
import { Injectable } from '@angular/core';
import { HttpEvent, HttpParams, HttpResponse } from '@angular/common/http';
import { combineLatest, first, map, Observable, of, shareReplay, switchMap } from 'rxjs';
import { RuntimeConfigService } from '@shared/context/config/app-config.service';
import { ApiConfig } from '@shared/context/config/app-config.model';
import { ClientService } from './client.service';
import { AppStateService } from '@shared/context/state/app-state.service';

/** Destino resuelto para un endpoint: lo que recibe ClientService. */
interface EndpointTarget {
  url: string;
  headers: { [key: string]: string };
  identity: string;
  withIdentity: boolean;
}

interface EndpointConfig {
  target: EndpointTarget;
  /** Claves del contexto fijo a inyectar en el body; undefined = todas. */
  injectContext?: string[];
}

/** Entrada de configuración `api.<key>` en phylax-config.json. */
@Injectable({
  providedIn: 'root',
})
export class ApiService {
  private readonly endpointCache = new Map<string, Observable<EndpointConfig>>();

  public constructor(
    private readonly appState: AppStateService,
    private readonly client: ClientService,
    private readonly config: RuntimeConfigService,
  ) {}

  get<T>(endpoint: string, params?: HttpParams): Observable<T> {
    return this.query(endpoint, params ?? null, (args) => this.client.get<T>(args));
  }

  post<T>(endpoint: string, body: any, params?: HttpParams): Observable<T> {
    return this.command(endpoint, body, params ?? null, (args) => this.client.post<T>(args));
  }

  download(endpoint: string, params?: HttpParams): Observable<HttpResponse<Blob>> {
    return this.query(endpoint, params ?? null, (args) => this.client.download(args));
  }

  upload(endpoint: string, name: string, file: File, params?: HttpParams): Observable<HttpEvent<any>> {
    return this.command(endpoint, null, params ?? null, (args) => this.client.upload({ name, file, ...args }));
  }

  put<T>(endpoint: string, body: any, params?: HttpParams): Observable<T> {
    return this.command(endpoint, body, params ?? null, (args) => this.client.put<T>(args));
  }

  patch<T>(endpoint: string, body: any, params?: HttpParams): Observable<T> {
    return this.command(endpoint, body, params ?? null, (args) => this.client.patch<T>(args));
  }

  delete<T>(endpoint: string, params?: any): Observable<T> {
    return this.command(endpoint, null, params ?? null, (args) => this.client.delete<T>(args));
  }

  /**
   * Lectura reactiva: se vuelve a lanzar cada vez que cambia el contexto de filtrado
   * (o la configuración del endpoint), cancelando la petición anterior.
   */
  private query<T>(
    endpoint: string,
    params: HttpParams | null,
    send: (args: EndpointTarget & { params: HttpParams }) => Observable<T>,
  ): Observable<T> {
    const conf$ = this.find(endpoint);
    return this.appState
      .filterContext()
      .pipe(
        switchMap((filter) =>
          conf$.pipe(switchMap((conf) => send({ ...conf.target, params: this.withFilter(params, filter) }))),
        ),
      );
  }

  /**
   * Mutación: toma una única instantánea del contexto y emite una sola petición;
   * un cambio de contexto posterior no la reenvía.
   */
  private command<T>(
    endpoint: string,
    body: any,
    params: HttpParams | null,
    send: (args: EndpointTarget & { params: HttpParams; body: any }) => Observable<T>,
  ): Observable<T> {
    const fixed$ = body ? this.appState.fixedContext() : of({});
    return combineLatest([this.appState.filterContext(), fixed$, this.find(endpoint)]).pipe(
      first(),
      switchMap(([filter, fixed, conf]) => {
        return send({
          ...conf.target,
          params: this.withFilter(params, filter),
          body: body ? this.withFixed(body, fixed, conf.injectContext) : body,
        });
      }),
    );
  }

  private withFilter(params: HttpParams | null, filter: any): HttpParams {
    let p = params ?? new HttpParams();
    Object.entries(filter ?? {}).forEach(([k, v]) => {
      if (v !== undefined && v !== null) {
        const val = v as any;
        p = p.set(k, String(val.$ref ? val.$ref : val)); // HttpParams es inmutable
      }
    });
    return p;
  }

  private withFixed(body: any, fixed: any, injectContext?: string[]): any {
    const effectiveBody = { ...body };
    Object.entries(fixed ?? {}).forEach(([k, v]) => {
      if (!injectContext || injectContext.includes(k)) {
        effectiveBody[k] = v;
      }
    });
    return effectiveBody;
  }

  /**
   * Resuelve el host lógico de una URL contra la configuración `api`.
   *
   * - `http(s)://<key>/…`: se usa la entrada cuya clave coincide exactamente con el host.
   * - Alternativa: `<key>/…` o `<api.url>/…` como prefijo (respetando el límite de segmento);
   *   si varias entradas coinciden gana el prefijo más largo.
   */
  private find(url: string): Observable<EndpointConfig> {
    const cached = this.endpointCache.get(url);
    if (cached) return cached;

    const obs = this.config.value$('api').pipe(
      map((apiConf) => {
        const match = this.bestMatch(url, apiConf ?? {});
        if (!match) {
          return { target: { url, headers: {}, identity: '', withIdentity: false } };
        }
        const { api, prefix } = match;
        return {
          target: {
            url: api.url ? api.url + url.substring(prefix.length) : url,
            headers: { ...(api.headers ?? {}) },
            identity: api.identity ?? '',
            withIdentity: !!api.identity,
          },
          injectContext: api['inject-context'],
        };
      }),
      shareReplay({ bufferSize: 1, refCount: false }),
    );

    this.endpointCache.set(url, obs);
    return obs;
  }

  private bestMatch(url: string, apiConf: { [key: string]: ApiConfig }): { api: ApiConfig; prefix: string } | null {
    const origin = /^https?:\/\/[^/?#]+/i.exec(url)?.[0];
    const host = origin ? this.hostOf(origin) : null;

    let best: { api: ApiConfig; prefix: string; score: number } | null = null;
    Object.entries(apiConf).forEach(([key, api]) => {
      const candidates: { prefix: string; score: number }[] = [];
      if (origin && host === key.toLowerCase()) {
        candidates.push({ prefix: origin, score: Number.MAX_SAFE_INTEGER });
      }
      [key, api.url].forEach((prefix) => {
        if (prefix && this.hasPrefix(url, prefix)) {
          candidates.push({ prefix, score: prefix.length });
        }
      });
      candidates.forEach((c) => {
        if (!best || c.score > best.score) {
          best = { api, ...c };
        }
      });
    });
    return best;
  }

  private hasPrefix(url: string, prefix: string): boolean {
    if (!url.startsWith(prefix)) {
      return false;
    }
    const next = url.charAt(prefix.length);
    return next === '' || prefix.endsWith('/') || next === '/' || next === '?' || next === '#';
  }

  private hostOf(origin: string): string | null {
    try {
      return new URL(origin).host;
    } catch {
      return null;
    }
  }
}
